mapper.select:
SELECT id, sku_id, normalized_serial, state, owner_warehouse_id, owner_epoch, claim_operation_id, transfer_id, receipt_operation_id, route_bucket, version
FROM serial_registry
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial} FOR UPDATE

SELECT id, sku_id, normalized_serial, state, owner_warehouse_id, owner_epoch, claim_operation_id, transfer_id, receipt_operation_id, route_bucket, version
FROM serial_registry
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}

mapper.update:
UPDATE serial_registry
SET state=#{toState}, transfer_id=#{transferId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND state=#{fromState}
AND owner_epoch=#{epoch}

UPDATE serial_registry
SET state='ACTIVE', owner_warehouse_id=#{warehouseId}, owner_epoch=#{toEpoch}, transfer_id=#{transferId}, receipt_operation_id=#{receiptOp}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND state='RECEIVING'
AND transfer_id=#{transferId}

UPDATE serial_registry
SET state=#{state}, receipt_operation_id=claim_operation_id, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND state='CLAIMED'

UPDATE serial_registry
SET state='MISSING', receipt_operation_id=#{factRef}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND state='ACTIVE'
AND owner_warehouse_id=#{warehouseId}
AND owner_epoch=#{epoch}

UPDATE serial_registry
SET state='FOUND_CLAIMED', owner_warehouse_id=#{warehouseId}, owner_epoch=owner_epoch+1, claim_operation_id=#{operationId}, receipt_operation_id=#{operationId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND state='MISSING'

UPDATE serial_registry
SET state='ACTIVE', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND sku_id=#{skuId}
AND normalized_serial=#{serial}
AND state='FOUND_CLAIMED'
AND claim_operation_id=#{operationId}

UPDATE serial_registry SET receipt_operation_id=claim_operation_id, version=version+1,updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND sku_id=#{skuId} AND normalized_serial=#{serial}
  AND owner_warehouse_id=#{warehouseId} AND claim_operation_id=#{operationId}
  AND state='ACTIVE' AND receipt_operation_id IS NULL AND transfer_id IS NULL

UPDATE serial_registry SET state='SHIPPED',version=version+1,updated_at=#{now}
WHERE enterprise_id=#{e} AND sku_id=#{sku} AND normalized_serial=#{serial} AND owner_warehouse_id=#{w}
AND owner_epoch=#{epoch} AND version=#{version} AND state='ACTIVE'
